export class Subject {
  constructor() {
    this.observers = [];
  }
  next(value) {
    for (const observer of this.observers.slice()) observer(value);
  }
  subscribe(observer) {
    this.observers.push(observer);
    return () => {
      const at = this.observers.indexOf(observer);
      if (at >= 0) this.observers.splice(at, 1);
    };
  }
  get observed() {
    return this.observers.length;
  }
}
export class BehaviorSubject extends Subject {
  constructor(initial) {
    super();
    this.current = initial;
  }
  next(value) {
    this.current = value;
    super.next(value);
  }
  subscribe(observer) {
    const stop = super.subscribe(observer);
    observer(this.current);
    return stop;
  }
  getValue() {
    return this.current;
  }
}
